match(node, position):
    if position == pattern.length:
        return terminal[node]

    ch = pattern[position]
    if ch == '.':
        for every child of node:
            if match(child, position + 1): return true
        return false

    child = edge labeled ch from node
    if child does not exist: return false
    return match(child, position + 1)
